def _digest(value: object, *, ascii: bool = False) -> str:
    return hashlib.sha256(
        json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=ascii).encode()
    ).hexdigest()


def _convert_configurations() -> None:
    """One offline cutover; no legacy readers remain in the application.

    Full original request bodies were not retained. Their digests deliberately
    remain historical: clients must use new request keys after this breaking cutover.
    Partial edge patches without an exact base cannot be reconstructed safely.
    """
    db = op.get_bind()
    db.execute(sa.text("SET CONSTRAINTS ALL IMMEDIATE"))
    if db.scalar(sa.text("SELECT EXISTS (SELECT 1 FROM runs WHERE status IN ('accepted', 'running'))")):
        raise RuntimeError("Drain accepted and running Runs before the subagents cutover")
    if db.scalar(
        sa.text("""
        SELECT EXISTS (
            SELECT 1 FROM runs WHERE
                jsonb_path_exists(checkpoint, '$.**.app.reference.agent_revision_id') OR
                jsonb_path_exists(tail, '$.**.app.reference.agent_revision_id')
            UNION ALL
            SELECT 1 FROM run_item_pages WHERE
                jsonb_path_exists(refs, '$.**.app.reference.agent_revision_id')
        )
    """)
    ):
        raise RuntimeError(
            "Retained MCP App bindings need an offline object rewrite or scoped history reset before cutover"
        )
    tables = ("agent_revisions", "runs", "inbox_entries", "schedules", "schedule_occurrences")
    for table in tables:
        db.execute(sa.text(f"ALTER TABLE {table} DISABLE TRIGGER USER"))
    revisions = {row.id: row.config for row in db.execute(sa.text("SELECT id, config FROM agent_revisions"))}

    def options(value: dict, revision_id: str | None) -> dict:
        override = value.get("overrides") or {}
        patch = override.get("subagents")
        if patch is None:
            return value
        if revision_id not in revisions:
            raise RuntimeError(
                "Legacy subagent patches need an exact revision; clear/reseed or pin affected queued inputs and Schedules before cutover"
            )
        base = revisions[revision_id]
        edges = dict(base.get("subagents", {}))
        for name, edge in patch.items():
            if edge is None:
                edges.pop(name, None)
                continue
            changes = {key: item for key, item in edge.items() if item is not None}
            if "agent_id" in changes and "revision_id" not in changes:
                changes["revision_id"] = None
            edges[name] = {
                "agent_id": None,
                "revision_id": None,
                "description": None,
                "context": {"include_task": True, "history": "none", "task_state": "shared"},
                "usage_limits": None,
                "environment": {"mode": "shared", "template_id": None},
                **edges.get(name, {}),
                **changes,
            }
            edges[name]["environment"] = {"mode": "shared", "template_id": None, **edges[name]["environment"]}
        return {
            **value,
            "overrides": {
                **override,
                "subagents": {
                    "mode": base.get("subagent_mode", "inline"),
                    "named": edges,
                    "dynamic": {
                        "enabled": False,
                        "allowed_models": [],
                        "default_model": None,
                        "default_thinking": None,
                    },
                },
            },
        }

    def write(table: str, identifier: str, column: str, value: dict, digest: str | None = None) -> None:
        suffix = f", {digest} = :digest" if digest else ""
        db.execute(
            sa.text(f"UPDATE {table} SET {column} = CAST(:value AS jsonb){suffix} WHERE id = :id"),
            {
                "id": identifier,
                "value": json.dumps(value),
                "digest": _digest(value, ascii=table == "agent_revisions"),
            },
        )

    for table in ("runs", "inbox_entries"):
        selection = (
            "agent_revision_id"
            if table == "runs"
            else "COALESCE(agent_revision_id, (SELECT agent_revision_id FROM runs WHERE id = inbox_entries.assigned_run_id))"
        )
        for row in db.execute(sa.text(f"SELECT id, {selection} AS agent_revision_id, options FROM {table}")):
            converted = options(row.options or {}, row.agent_revision_id)
            if converted != row.options:
                write(table, row.id, "options", converted)
    for table, column in (("schedules", "invocation"), ("schedule_occurrences", "snapshot")):
        for row in db.execute(sa.text(f"SELECT id, {column} AS value FROM {table}")):
            value = row.value
            invocation = value if table == "schedules" else value.get("invocation", {})
            converted = options(invocation.get("options") or {}, invocation.get("agent_revision_id"))
            if converted != invocation.get("options", {}):
                invocation = {**invocation, "options": converted}
                write(
                    table,
                    row.id,
                    column,
                    invocation if table == "schedules" else {**value, "invocation": invocation},
                )
    _rewrite_option_digests(db)
    for identifier, config in revisions.items():
        converted = dict(config)
        mode = converted.pop("subagent_mode", "inline")
        converted["subagents"] = {
            "mode": mode,
            "named": converted.get("subagents", {}),
            "dynamic": {"enabled": False, "allowed_models": [], "default_model": None, "default_thinking": None},
        }
        write("agent_revisions", identifier, "config", converted, "digest")
    for table in reversed(tables):
        db.execute(sa.text(f"ALTER TABLE {table} ENABLE TRIGGER USER"))


def _restore_configurations() -> None:
    db = op.get_bind()
    db.execute(sa.text("SET CONSTRAINTS ALL IMMEDIATE"))
    if db.scalar(sa.text("SELECT EXISTS (SELECT 1 FROM threads WHERE agent_snapshot IS NOT NULL)")):
        raise RuntimeError("Cannot downgrade retained task snapshots")
    revisions = {row.id: row.config for row in db.execute(sa.text("SELECT id, config FROM agent_revisions"))}

    def old_policy(policy: dict) -> tuple[str, dict]:
        dynamic = policy.get("dynamic") or {}
        if (
            dynamic.get("enabled")
            or dynamic.get("allowed_models")
            or dynamic.get("default_model") is not None
            or dynamic.get("default_thinking") is not None
        ):
            raise RuntimeError("Cannot downgrade dynamic subagent policies")
        return policy.get("mode", "async"), policy.get("named", {})

    def options(value: dict, revision_id: str | None) -> dict:
        override = value.get("overrides") or {}
        policy = override.get("subagents")
        if policy is None:
            return value
        mode, named = old_policy(policy)
        if revision_id not in revisions:
            raise RuntimeError("Cannot downgrade a replacement policy without its exact revision")
        base_mode, base_named = old_policy(revisions[revision_id].get("subagents", {}))
        if mode != base_mode:
            raise RuntimeError("Cannot downgrade a subagent mode override")
        return {**value, "overrides": {**override, "subagents": {**dict.fromkeys(base_named), **named}}}

    for config in revisions.values():
        old_policy(config.get("subagents", {}))
    tables = ("agent_revisions", "runs", "inbox_entries", "schedules", "schedule_occurrences")
    for table in tables:
        db.execute(sa.text(f"ALTER TABLE {table} DISABLE TRIGGER USER"))
    for table in ("runs", "inbox_entries"):
        selection = (
            "agent_revision_id"
            if table == "runs"
            else "COALESCE(agent_revision_id, (SELECT agent_revision_id FROM runs WHERE id = inbox_entries.assigned_run_id))"
        )
        for row in db.execute(sa.text(f"SELECT id, {selection} AS agent_revision_id, options FROM {table}")):
            converted = options(row.options or {}, row.agent_revision_id)
            if converted != row.options:
                db.execute(
                    sa.text(f"UPDATE {table} SET options = CAST(:value AS jsonb) WHERE id = :id"),
                    {"id": row.id, "value": json.dumps(converted)},
                )
    for table, column in (("schedules", "invocation"), ("schedule_occurrences", "snapshot")):
        for row in db.execute(sa.text(f"SELECT id, {column} AS value FROM {table}")):
            value = row.value
            invocation = value if table == "schedules" else value.get("invocation", {})
            converted = options(invocation.get("options") or {}, invocation.get("agent_revision_id"))
            if converted != invocation.get("options", {}):
                invocation = {**invocation, "options": converted}
                changed = invocation if table == "schedules" else {**value, "invocation": invocation}
                db.execute(
                    sa.text(f"UPDATE {table} SET {column} = CAST(:value AS jsonb) WHERE id = :id"),
                    {"id": row.id, "value": json.dumps(changed)},
                )
    _rewrite_option_digests(db)
    for identifier, config in revisions.items():
        mode, named = old_policy(config.get("subagents", {}))
        converted = {**config, "subagent_mode": mode, "subagents": named}
        db.execute(
            sa.text("UPDATE agent_revisions SET config = CAST(:value AS jsonb), digest = :digest WHERE id = :id"),
            {"id": identifier, "value": json.dumps(converted), "digest": _digest(converted, ascii=True)},
        )
    for table in reversed(tables):
        db.execute(sa.text(f"ALTER TABLE {table} ENABLE TRIGGER USER"))


def _rewrite_option_digests(db) -> None:
    """Preserve the submitted-options owner; Run options omit nulls and include frozen pins."""
    entries = {row.id: row for row in db.execute(sa.text("SELECT id, kind, origin_run_id, options FROM inbox_entries"))}
    digests = {}
    runs = db.execute(
        sa.text("SELECT id, source_entry_id, parent_run_id, options_digest FROM runs ORDER BY created_at, id")
    ).all()
    for run in runs:
        entry = entries.get(run.source_entry_id)
        if entry is not None and entry.kind == "message":
            value = {
                key: item for key, item in entry.options.items() if key not in {"configuration", "execution", "context"}
            }
            digest = _digest(value)
        else:
            origin = entry.origin_run_id if entry is not None else run.parent_run_id
            if origin not in digests:
                raise RuntimeError(
                    "Cannot reconstruct the submitted-options owner; clear/reseed affected obsolete history"
                )
            digest = digests[origin]
        digests[run.id] = digest
        if digest != run.options_digest:
            db.execute(
                sa.text("UPDATE runs SET options_digest = :digest WHERE id = :id"), {"id": run.id, "digest": digest}
            )
